import java.util.ArrayList;
import java.util.List;

class Solution {
    public List<List<Integer>> combinationSum(int[] candidates, int target) {
        List<List<Integer>> result = new ArrayList<>();
        enumerate(candidates, 0, target, new ArrayList<>(), result);
        return result;
    }

    private void enumerate(int[] candidates, int index, int remaining, List<Integer> current, List<List<Integer>> result) {
        if (remaining == 0) {
            result.add(new ArrayList<>(current));
            return;
        }
        if (index == candidates.length) {
            return;
        }
        enumerate(candidates, index + 1, remaining, current, result);
        if (candidates[index] <= remaining) {
            current.add(candidates[index]);
            enumerate(candidates, index, remaining - candidates[index], current, result);
            current.remove(current.size() - 1);
        }
    }
}

