import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

class Solution {
    public List<List<Integer>> combinationSum(int[] candidates, int target) {
        int[] sorted = candidates.clone();
        Arrays.sort(sorted);
        List<List<Integer>> result = new ArrayList<>();
        build(sorted, 0, target, new ArrayList<>(), result);
        return result;
    }

    private void build(int[] candidates, int start, int remaining, List<Integer> current, List<List<Integer>> result) {
        if (remaining == 0) {
            result.add(new ArrayList<>(current));
            return;
        }
        for (int index = start; index < candidates.length; index++) {
            if (candidates[index] > remaining) {
                break;
            }
            current.add(candidates[index]);
            build(candidates, index, remaining - candidates[index], current, result);
            current.remove(current.size() - 1);
        }
    }
}
